function LandingPage(){return <div className="landing salesLanding"><header className="landingNav salesNav"><button className="landingBrand landingBrandButton" type="button" onClick={()=>window.scrollTo({top:0,behavior:'smooth'})}><span className="brandSymbol">N</span><span>NEXA</span></button><nav aria-label="ページナビゲーション"><button type="button" onClick={()=>scrollTo('demo')}>デモ</button><button type="button" onClick={()=>scrollTo('usecases')}>活用例</button><button type="button" onClick={()=>scrollTo('features')}>機能</button><button type="button" onClick={()=>scrollTo('customize')}>カスタマイズ</button><button type="button" onClick={()=>scrollTo('safety')}>安心・安全</button></nav><button className="navButton" type="button" onClick={()=>scrollTo('launch')}>プラットフォームを見る</button></header><main><section className="salesHero" id="top"><div className="heroAmbient"/><div className="heroRings"/><div className="salesHeroCopy"><span className="salesEyebrow"><i/> UNIVERSAL MATCHING PLATFORM · COMMERCIAL TEMPLATE</span><h1>買って終わりじゃない。<br/><em>あなたの</em>サービスになる。</h1><p>完成されたマッチング体験を、ゼロから作らずに。購入後はブランド、対象市場、ルール、機能まで変えられる。見た目だけのテンプレートではなく、実際に触れて価値を確認できるプロダクト基盤です。</p><div className="salesHeroActions"><button className="salesPrimary" type="button" onClick={()=>scrollTo('demo')}>すべての機能を体験する <span>↘</span></button><button className="salesTextButton" type="button" onClick={()=>scrollTo('customize')}>そのまま使う。自由に変える。 <span>↓</span></button></div><div className="heroTrust"><span>WEB</span><span>iOS</span><span>ANDROID</span><span>GLOBAL</span></div></div><div className="salesHeroVisual"><div className="heroBuyerBadge"><span>COMMERCIAL-READY</span><b>販売できる完成形を、ここから。</b></div><MiniProduct/><div className="heroValueRail"><div><strong>01</strong><span>そのまま公開</span></div><div><strong>02</strong><span>ブランド変更</span></div><div><strong>03</strong><span>自由に拡張</span></div></div><div className="floatingStat"><strong>8+</strong><span>主要機能を体験</span></div><div className="floatingStat second"><strong>WEB</strong><span>iOS / Android対応</span></div></div><button className="heroScroll" type="button" onClick={()=>scrollTo('demo')}>実際のデモを見る <i/></button></section><FullProductDemo/><section className="salesIntro" id="intro"><div className="salesSectionTop"><span>01 / コンセプト</span><span>ひとつの用途だけのアプリではない</span></div><div className="introHeadline"><h2>ゼロから<br/><em>始めない。</em></h2><div><p>人と人を目的に合わせてつなぐサービスをつくるための、プレミアムな基盤です。デザイン、プロダクト構造、運用まで考えた土台があるから、購入者はゼロから作り直すのではなく、自分の市場づくりに集中できます。</p><button type="button" onClick={()=>scrollTo('features')}>含まれるものを見る <span>↘</span></button></div></div><div className="introManifest"><span>01</span><b>目的を決める</b><span>→</span><b>体験をつくる</b><span>→</span><b>自分のサービスにする</b></div></section><section className="useCaseSection" id="usecases"><div className="sectionHeading"><div><span className="salesEyebrow">02 / ひとつの基盤 · 多くの市場</span><h2>誰と誰を<br/><em>つなぐ？</em></h2></div><p>同じ基盤から、恋愛、友だち、ビジネス、メンター、地域コミュニティ、専門サービスなど、さまざまなマッチングサービスへ展開できます。用途は購入者が決められます。</p></div><div className="useCaseGrid">{useCases.map(([n,t,d])=><article key={n}><span>{n}</span><div><h3>{t}</h3><p>{d}</p></div><b>↗</b></article>)}</div></section><section className="featureSection" id="features"><div className="featureIntro"><span className="salesEyebrow">03 / プラットフォーム</span><h2>サービスに必要なものを<br/><em>ひとつの基盤に。</em></h2><p>マッチングだけではありません。プロフィール、メッセージ、通知、安心・安全、管理、分析、グローバル、決済、Web / iOS / Androidまで、サービスとして成立させるための土台をまとめています。</p></div><div className="featureList">{featureGroups.map(([n,t,d])=><article key={n}><span className="featureNo">{n}</span><div><h3>{t}</h3><p>{d}</p></div><span className="featurePlus">+</span></article>)}</div></section><section className="customSection" id="customize"><div className="customHeader"><span className="salesEyebrow">04 / 自分のサービスへ</span><h2>すぐ使える。<br/><em>方向性は、自分で決める。</em></h2></div><div className="customSplit"><article className="customCard ready"><span className="cardKicker">クイックローンチ</span><div className="cardNumber">01</div><h3>デザインは活かす。<br/><em>ブランドを変える。</em></h3><p>ロゴ、カラー、画像、言語、用語、利用規約・サポート情報などを変更して公開できます。</p><div className="customItems"><span>ロゴ・カラー</span><span>画像・文字デザイン</span><span>言語・地域</span><span>プロフィール項目</span></div></article><article className="customCard developer"><span className="cardKicker">高度なカスタマイズ</span><div className="cardNumber">02</div><h3>ルールを変える。<br/><em>違うサービスにする。</em></h3><p>ソースコードをカスタマイズし、マッチングロジック、プロフィール、導線、API、新機能まで拡張できます。</p><div className="customItems"><span>マッチングアルゴリズム</span><span>機能の表示設定</span><span>API・Webhook</span><span>独自のサービスロジック</span></div></article></div><div className="customBottom"><span>完成するもの</span><strong>購入したサービスの雰囲気を残すことも、自分で作ったようなサービスに変えることもできます。</strong></div></section><section className="safetySection" id="safety"><div className="safetyVisual"><div className="shieldCore">N</div><div className="safetyOrbit o1"/><div className="safetyOrbit o2"/><div className="safetyBadge">安心 / はじめから設計</div></div><div className="safetyCopy"><span className="salesEyebrow">05 / 安心・安全</span><h2>プレミアムとは、<br/><em>責任まで考えること。</em></h2><p>プライバシーと安全性を後付けにしない。最初の利用体験から、通報、モデレーション、管理まで、安心して運営できるサービス設計を目指します。</p><div className="safetyPoints"><span>プライバシー設定</span><span>通報・ブロック</span><span>モデレーション</span><span>監査ログ</span><span>不正・迷惑行為対策</span><span>位置情報の保護</span></div></div></section><section className="globalSection"><div><span className="salesEyebrow">06 / グローバル設計</span><h2>どの市場にも<br/><em>合わせられる。</em></h2></div><div className="globalMap"><div className="mapLines"/><span className="mapPin p1">日本</span><span className="mapPin p2">EU</span><span className="mapPin p3">米国</span><span className="mapPin p4">東南アジア</span><div className="mapCaption"><b>地域に合わせて設定</b><span>国 · 地域 · 都市 · 言語 · タイムゾーン</span></div></div></section><section className="launchSection" id="launch"><div className="launchInner"><span className="salesEyebrow">07 / 次のサービスへ</span><h2>基盤を手に入れる。<br/><em>つながりをつくる。</em></h2><p>本気のマッチングサービスを始めるための、洗練された出発点。そのまま使えて、自由に変えられて、自分のサービスにできます。</p><div className="launchActions"><button className="salesPrimary dark" type="button" onClick={()=>scrollTo('demo')}>実際の製品を体験する <span>↗</span></button><button className="salesTextButton darkText" type="button" onClick={()=>scrollTo('top')}>トップへ戻る ↑</button></div></div></section></main><footer className="landingFooter salesFooter"><button className="landingBrand landingBrandButton" type="button" onClick={()=>window.scrollTo({top:0,behavior:'smooth'})}><span className="brandSymbol">N</span><span>NEXA</span></button><span>ユニバーサル・マッチングプラットフォーム · Web · iOS · Android</span><span>© 2026</span></footer></div>}
createRoot(document.getElementById('root')!).render(<React.StrictMode><LandingPage/></React.StrictMode>);
